def solution(gems):
    def check_all_types(start, end, gem_types):
        return len(set(gems[start:end])) == gem_types

    def find_shortest_range(start, end, gem_types, shortest):
        if end >= len(gems):
            return shortest
        if check_all_types(start, end, gem_types):
            shortest = min(shortest, end - start)
            return find_shortest_range(start, end + 1, gem_types, shortest)
        else:
            return find_shortest_range(start, end + 1, gem_types, shortest)

    gem_types = len(set(gems))
    return find_shortest_range(0, 1, gem_types, float('inf')) + 1 if gem_types else 0

