def solution(works, n):
    import heapq
    if sum(works) <= n:
        return 0
    works = [-work for work in works]
    heapq.heapify(works)
    for _ in range(n):
        largest = heapq.heappop(works)
        if largest < 0:
            heapq.heappush(works, largest + 1)
    return sum(work ** 2 for work in works)

