        if num == 0:
            return ''
        return to_base_3(num // 3) + str(num % 3)

    def reverse_string(s):
        if s == '':
            return ''
        return s[-1] + reverse_string(s[:-1])

    def to_decimal(s):
        if s == '':
            return 0
        return int(s[-1]) * (3 ** (len(s) - 1)) + to_decimal(s[:-1])

    base_3 = to_base_3(n)
    reversed_base_3 = reverse_string(base_3)
    return to_decimal(reversed_base_3)

