def solution(orders, course):
    from itertools import combinations
    from collections import Counter

    def generate_combinations(order, course_size, start=0, current_combination=''):
        if len(current_combination) == course_size:
            combination_counter[current_combination] += 1
            return
        for i in range(start, len(order)):
            generate_combinations(order, course_size, i + 1, current_combination + order[i])

    combination_counter = Counter()
    for order in orders:
        order = ''.join(sorted(order))
        for size in course:
            generate_combinations(order, size)

    result = []
    for size in course:
        most_common = combination_counter.most_common()
        max_count = 0
        for comb, count in most_common:
            if len(comb) == size:
                if count > max_count and count >= 2:
                    max_count = count
                    result = [comb]
                elif count == max_count and count >= 2:
                    result.append(comb)

    return sorted(result)

def solution(n):
    def sum_digits(num):
        if num == 0:
            return 0
        return num % 10 + sum_digits(num // 10)

    def sort_digits(num):
        digits = list(str(num))
        if len(digits) <= 1:
            return digits
        max_digit = max(digits)
        digits.remove(max_digit)
        return [max_digit] + sort_digits(''.join(digits))

    digit_sum = sum_digits(n)
    sorted_digits = sort_digits(digit_sum)
    return int(''.join(sorted_digits))

