def solution(relation):
    from itertools import combinations

    def is_unique(candidate):
        seen = set()
        for row in relation:
            key = tuple(row[i] for i in candidate)
            if key in seen:
                return False
            seen.add(key)
        return True

    def is_minimal(candidate, candidates):
        for other in candidates:
            if set(other).issubset(set(candidate)):
                return False
        return True

    def find_candidates(start, current):
        if start == len(attributes):
            return

        for i in range(start, len(attributes)):
            new_candidate = current + [i]
            if is_unique(new_candidate) and is_minimal(new_candidate, candidates):
                candidates.append(new_candidate)
            find_candidates(i + 1, new_candidate)

    attributes = range(len(relation[0]))
    candidates = []
    find_candidates(0, [])
    return len(candidates)

