def solution(n, info):
    def dfs(idx, arrows_left, score_distribution):
        if idx == 11 or arrows_left == 0:
            if arrows_left > 0:
                score_distribution[idx] += arrows_left
            score = calculate_score(score_distribution)
            update_best(score_distribution, score)
            return

        score_distribution[idx] = 0
        dfs(idx + 1, arrows_left, score_distribution)

        if arrows_left > 0:
            score_distribution[idx] += 1
            dfs(idx, arrows_left - 1, score_distribution)
            score_distribution[idx] -= 1

        dfs(idx + 1, arrows_left, score_distribution)

    def calculate_score(score_distribution):
        lion_score = 0
        apeach_score = 0
        for i in range(11):
            if score_distribution[i] > info[i]:
                lion_score += 10 - i
            elif info[i] > 0:
                apeach_score += 10 - i
        return lion_score - apeach_score

    def update_best(score_distribution, score):
        nonlocal best_score, best_distribution
        if score > best_score:
            best_score = score
            best_distribution = score_distribution[:]
        elif score == best_score:
            for i in range(10, -1, -1):
                if score_distribution[i] > best_distribution[i]:
                    best_distribution = score_distribution[:]
                    break
                elif score_distribution[i] < best_distribution[i]:
                    break

    best_score = -1
    best_distribution = [0] * 11
    dfs(0, n, [0] * 11)
    return best_distribution

