            return fees[1]
        else:
            extra_time = total_minutes - fees[0]
            extra_fee = (extra_time + fees[2] - 1) // fees[2] * fees[3]
            return fees[1] + extra_fee

    parking = {}
    for record in records:
        time, car_number, action = record.split()
        if action == 'IN':
            parking[car_number] = time_to_minutes(time)
        else:
            if car_number in parking:
                total_minutes = time_to_minutes(time) - parking[car_number]
                parking[car_number] = total_minutes

    result = {}
