        if isinstance(minutes, int):
            total_minutes = minutes
        else:
            total_minutes = time_to_minutes("23:59") - minutes
        result[car_number] = calculate_fee(total_minutes)

    sorted_result = sorted(result.items())
    return [fee for _, fee in sorted_result]

