                if board[i][j] and board[i][j] == board[i][j + 1] == board[i + 1][j] == board[i + 1][j + 1]:
                    to_remove.update({(i, j), (i, j + 1), (i + 1, j), (i + 1, j + 1)})
        for i, j in to_remove:
