        queue = deque([(start_row, start_col)])
        component = []
        while queue:
            row, col = queue.popleft()
            if visited[row][col]:
                continue
            visited[row][col] = True
            component.append((row, col))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                new_row, new_col = row + dr, col + dc
                if 0 <= new_row < n and 0 <= new_col < m and not visited[new_row][new_col] and storage[new_row][new_col] == storage[start_row][start_col]:
                    queue.append((new_row, new_col))
        return component

    results = []

    for request in requests:
        found = False
        for i in range(n):
            for j in range(m):
                if storage[i][j] == request and not visited[i][j]:
                    component = bfs(i, j)
                    results.extend(component)
                    found = True
                    break
            if found:
                break

    return results

