def solution(key, lock):
    lock_size = len(lock)
    key_size = len(key)
    extended_lock_size = lock_size + 2 * (key_size - 1)
    extended_lock = [[0] * extended_lock_size for _ in range(extended_lock_size)]

    for i in range(lock_size):
        for j in range(lock_size):
            extended_lock[i + key_size - 1][j + key_size - 1] = lock[i][j]

    def check(lock_part):
        for i in range(lock_size):
            for j in range(lock_size):
                if lock_part[i + key_size - 1][j + key_size - 1] == 0:
                    return False
        return True

    for rotation in range(4):
        if rotation > 0:
            key = [[key[key_size - 1 - j][i] for j in range(key_size)] for i in range(key_size)]

        for x in range(extended_lock_size - key_size + 1):
            for y in range(extended_lock_size - key_size + 1):
                for i in range(key_size):
                    for j in range(key_size):
                        extended_lock[x + i][y + j] += key[i][j]

                if check(extended_lock):
