    def minute_add(str_time,t):
        str_time = datetime.datetime.strptime(str_time,timeformat) + datetime.timedelta(minutes = t)
        return str_time.strftime(timeformat)

    for bus_cnt in range(n):
        #m명 만큼 탑승시킨다.
        for _ in range(m):
            #버스가 도착하고 최대 m명을 탑승시킨다.
