                #마지막에 탄 손님의 시간이 계산된다.
                last_passenger = timetable.pop(0)
                if bus_cnt == n-1:
                    cnt_last_passenger += 1

        #bus시간을 증가시킨다.
        bus_time = minute_add(bus_time,t)

    #마지막버스에 모두가 탑승한 경우 맨 마지막 손님보다 1분 일찍 도착한다.
