        if pick_index >= len(picks) or mineral_index >= len(minerals):
            return current_fatigue

        if picks[pick_index] == 0:
            return dfs(pick_index + 1, mineral_index, current_fatigue)

        fatigue = 0
        if mineral_index < len(minerals):
            fatigue = (1 if minerals[mineral_index] == 'diamond' else 2 if minerals[mineral_index] == 'iron' else 3)
