                if direction == 0 and (nx, ny) not in visited:
                    visited.add((nx, ny, 0))
                    queue.append((nx, ny, 0))
                elif direction == 1 and (nx, ny) not in visited:
                    visited.add((nx, ny, 1))
                    queue.append((nx, ny, 1))

        if direction == 0:
            if x + 1 < n and board[x + 1][y] == 0 and (x, y, 1) not in visited:
                visited.add((x, y, 1))
                queue.append((x, y, 1))
            if y + 1 < n and board[x][y + 1] == 0 and (x, y + 1, 1) not in visited:
                visited.add((x, y + 1, 0))
                queue.append((x, y + 1, 0))
        else:
            if x < n - 1 and board[x][y] == 0 and (x, y, 0) not in visited:
                visited.add((x, y, 0))
                queue.append((x, y, 0))
            if y < n - 1 and board[x][y + 1] == 0 and (x + 1, y, 0) not in visited:
