def solution(s):
    def insert_and_find(s, idx, target):
        if idx > len(s):
            return []
        new_s = s[:idx] + target + s[idx:]
        return [new_s] + insert_and_find(s, idx + 1, target)

    def find_min_string(s):
        target = "111"
        if target not in s:
            return s
        s_without_target = s.replace(target, "")
        possible_strings = insert_and_find(s_without_target, 0, target)
        return min(possible_strings)

    return find_min_string(s)

