def solution(n, lost, reserve):
    lost_set = set(lost) - set(reserve)
    reserve_set = set(reserve) - set(lost)

    def count_students(lost_list, reserves):
        if not lost_list:
            return n - len(lost)
        if not reserves:
            return n - len(lost_list)

        current_lost = lost_list[0]
        without_borrow = count_students(lost_list[1:], reserves)

        if current_lost - 1 in reserves:
            with_borrow = count_students(lost_list[1:], reserves - {current_lost - 1})
            return max(without_borrow, with_borrow)
        if current_lost + 1 in reserves:
            with_borrow = count_students(lost_list[1:], reserves - {current_lost + 1})
            return max(without_borrow, with_borrow)

        return without_borrow

    return count_students(sorted(lost_set), reserve_set)

def solution(n, m, x, y, queries):
    for direction, steps in queries:
        if direction == 1: 
            y = min(m, y + steps)
        elif direction == 2: 
            y = max(1, y - steps)
        elif direction == 3: 
            x = max(1, x - steps)
        elif direction == 4: 
            x = min(n, x + steps)
    return (x, y)

