def solution(n):
    def fibonacci_sum(k):
        if k == 0:
            return 0
        elif k == 1:
            return 1
        else:
            return fibonacci_sum(k - 1) + fibonacci_sum(k - 2) + fibonacci_sum(k - 3)

    total_sum = sum(fibonacci_sum(i) for i in range(n + 1))
    return total_sum % 1234567

