def solution(arr1, arr2):
    def multiply_recursive(row, col, sum_val):
        if col == len(arr2[0]):
            return sum_val
        if row == len(arr1):
            return []
        if sum_val == 0:
            sum_val = sum(arr1[row][k] * arr2[k][col] for k in range(len(arr2)))
            return [sum_val] + multiply_recursive(row, col + 1, 0)
        return multiply_recursive(row, col, 0) if col == 0 else multiply_recursive(row + 1, 0, 0)

    return [multiply_recursive(i, 0, 0) for i in range(len(arr1))]

