def solution(e, starts):
    from collections import Counter
    import math

    def count_sqrt(start, end, counts):
        if start > end:
            return counts
        sqrt_value = int(math.sqrt(start))
        counts[sqrt_value] += 1
        return count_sqrt(start + 1, end, counts)

    counts = Counter()
    count_sqrt(starts, e, counts)

    max_count = max(counts.values())
    candidates = [num for num, count in counts.items() if count == max_count]

    return min(candidates)

