from itertools import combinations

def solution(orders, course):
    result = []
    for c in course:
        count = {}
        for order in orders:
            for o in combinations(order , c):
                key = ''.join(sorted(o))
                count.setdefault(key, 0)
                count[key] += 1
        if len(count.keys()) == 0:
            break
        max_count = count[max(count, key=count.get)]
        if max_count > 1:
            for key in count.keys():
                if count[key] == max_count:
                    result.append(key)
    return sorted(result)

def solution(city, road):
    import heapq
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v, speed in road:
        graph[u].append((v, speed))
        graph[v].append((u, speed))

    def dijkstra(start):
        max_speed = [0] * (city + 1)
        max_speed[start] = float('inf')
        pq = [(-max_speed[start], start)]

        while pq:
            current_speed, current_city = heapq.heappop(pq)
            current_speed = -current_speed

            for neighbor, speed in graph[current_city]:
                new_speed = min(current_speed, speed)
                if new_speed > max_speed[neighbor]:
                    max_speed[neighbor] = new_speed
                    heapq.heappush(pq, (-new_speed, neighbor))

        return max_speed[1:]

    return dijkstra(1)

