def solution(numbers, hand):
    def get_position(num):
        if num == 0:
            return (3, 1)
        return (num // 3, num % 3)

    def distance(pos1, pos2):
        return abs(pos1[0] - pos2[0]) + abs(pos1[1] - pos2[1])

    def press_number(num, left_pos, right_pos, result):
        if num in [1, 4, 7]:
            result += 'L'
            return get_position(num), right_pos, result
        elif num in [3, 6, 9]:
            result += 'R'
            return left_pos, get_position(num), result
        else:
            target_pos = get_position(num)
            left_dist = distance(left_pos, target_pos)
            right_dist = distance(right_pos, target_pos)
            if left_dist < right_dist or (left_dist == right_dist and hand == 'left'):
                result += 'L'
                return target_pos, right_pos, result
            else:
                result += 'R'
                return left_pos, target_pos, result

    left_pos = (3, 0)
    right_pos = (3, 2)
    result = ''

    def recursive_press(index):
        nonlocal left_pos, right_pos, result
        if index >= len(numbers):
            return
        left_pos, right_pos, result = press_number(numbers[index], left_pos, right_pos, result)
        recursive_press(index + 1)

    recursive_press(0)
    return result

