def solution(N, stages):
    def calculate_failure_rate(stage, players):
        if stage > N:
            return []
        failed = sum(1 for s in stages if s == stage)
        total = sum(1 for s in stages if s >= stage)
        failure_rate = (failed / total) if total > 0 else 0
        return [(stage, failure_rate)] + calculate_failure_rate(stage + 1, players - failed)

    failure_rates = calculate_failure_rate(1, len(stages))
    failure_rates.sort(key=lambda x: (-x[1], x[0]))
    return [stage for stage, rate in failure_rates]

def solution(n, l, r):
    def count_ones(n, start, end):
        if n == 0:
            return 1 if start <= 0 <= end else 0
        length = 5 ** n
        mid_start = (length - 5) // 2
        mid_end = mid_start + 5

        count = 0
        if end < mid_start:
            count += count_ones(n - 1, start, end)
        elif start > mid_end:
            count += count_ones(n - 1, start - mid_end, end - mid_end)
        else:
            count += count_ones(n - 1, start, mid_start) + count_ones(n - 1, 0, end - mid_end)

        return count

    return count_ones(n - 1, l, r)

