    if total % 2 != 0:
        return -1
    target = total // 2

    def helper(q1, q2, sum1, sum2, count):
        if sum1 == target:
            return count
        if sum1 > target:
            return helper(q1[1:], q2 + [q1[0]], sum1 - q1[0], sum2 + q1[0], count + 1)
        return helper(q1 + [q2[0]], q2[1:], sum1 + q2[0], sum2 - q2[0], count + 1)

