def solution(x, y, n):
    memo = {}

    def dfs(current):
        if current > y:
            return float('inf')
        if current == y:
            return 0
        if current in memo:
            return memo[current]

        add_n = dfs(current + n) + 1
        multiply_2 = dfs(current * 2) + 1
        multiply_3 = dfs(current * 3) + 1

        memo[current] = min(add_n, multiply_2, multiply_3)
        return memo[current]

    result = dfs(x)
    return result if result != float('inf') else -1

