def solution(expression):
    import re
    from itertools import permutations

    nums = list(map(int, re.findall(r'\d+', expression)))
    ops = re.findall(r'[\+\-\*]', expression)

    max_result = float('-inf')

    for order in permutations(set(ops)):
        temp_nums = nums[:]
        temp_ops = ops[:]

        for op in order:
            while op in temp_ops:
                idx = temp_ops.index(op)
                if op == '+':
                    result = temp_nums[idx] + temp_nums[idx + 1]
                elif op == '-':
                    result = temp_nums[idx] - temp_nums[idx + 1]
                else:
                    result = temp_nums[idx] * temp_nums[idx + 1]

                temp_nums[idx:idx + 2] = [result]
                temp_ops.pop(idx)

        max_result = max(max_result, abs(temp_nums[0]))

    return max_result

