    # (a[i] < a[j] and b[i] < b[j]) - a는 sort 해놓음
    # else : 두 점수 합 높은 순 <- 인센티브 차등 지급
        # 동석차의 수 만큼 다음 석차 건너 뛰기 (공동 석차)

    index_scores = [[x[0], x[1], i] for i, x in enumerate(scores)]
