    rank = 0
    same_rank = 0
    sum_scores = -1
    for a, b, idx in insentive:
        if sum_scores == (a + b):
            same_rank += 1
        else:
            if same_rank == 0:
                rank += 1
            else:
                rank += 1
                rank += same_rank
                same_rank = 0
            sum_scores = (a + b)
        if idx == 0:
            return rank

