    def fill_spiral(x, y, num, direction):
        if num > n * n:
            return
        result[x][y] = num
        if direction == 0:
            if y + 1 < n and result[x][y + 1] == 0:
                fill_spiral(x, y + 1, num + 1, direction)
            else:
                fill_spiral(x + 1, y, num + 1, 1)
        elif direction == 1:
            if x + 1 < n and result[x + 1][y] == 0:
                fill_spiral(x + 1, y, num + 1, direction)
            else:
                fill_spiral(x, y - 1, num + 1, 2)
        elif direction == 2:
            if y - 1 >= 0 and result[x][y - 1] == 0:
                fill_spiral(x, y - 1, num + 1, direction)
            else:
                fill_spiral(x - 1, y, num + 1, 3)
        elif direction == 3:
            if x - 1 >= 0 and result[x - 1][y] == 0:
                fill_spiral(x - 1, y, num + 1, direction)
            else:
                fill_spiral(x, y + 1, num + 1, 0)

    result = [[0] * n for _ in range(n)]
    fill_spiral(0, 0, 1, 0)
    return [num for row in result for num in row]

def solution(n, build_frame):
    def is_valid(installed):
        for x, y, a in installed:
            if a == 0:  # 기둥
                if y == 0 or (x, y - 1, 0) in installed or (x, y, 1) in installed or (x - 1, y, 1) in installed:
                    continue
                return False
            else:  # 보
                if (x, y - 1, 0) in installed or (x + 1, y - 1, 0) in installed or ((x - 1, y, 1) in installed and (x + 1, y, 1) in installed):
                    continue
                return False
        return True

    def dfs(installed, index):
        if index == len(build_frame):
            if is_valid(installed):
                results.add(tuple(sorted(installed)))
            return

        x, y, a, state = build_frame[index]
        if state == 1:  # 설치
            installed.append((x, y, a))
            if is_valid(installed):
                dfs(installed, index + 1)
            installed.pop()
            dfs(installed, index + 1)
        else:  # 제거
            installed.remove((x, y, a))
            if is_valid(installed):
                dfs(installed, index + 1)
            installed.append((x, y, a))
            dfs(installed, index + 1)

    results = set()
    dfs([], 0)
    return [list(result) for result in sorted(results)]

