def solution(numbers, hand):
    answer = ''
    pad = {1: [0, 0], 2: [0, 1], 3: [0, 2],4: [1, 0], 5: [1, 1], 6: [1, 2],7: [2, 0], 8: [2, 1], 9: [2, 2],'*':[3, 0], 0: [3, 1], '#': [3, 2]}
    L = pad['*']
    R = pad['#']
    for i in numbers:
        now = pad[i]
        if i in [1,4,7]:
            answer += "L"
            L = now
        elif i in [3,6,9]:
            answer += "R"
            R = now
        else:
            left = 0
            right = 0
            for x,y,z in zip(L,R,now):
                left += abs(x-z)
                right += abs(y-z)
            if left < right or (left == right and hand == 'left'):
                answer += "L"
                L = now
            else:
                answer += "R"
                R = now
    return answer

def solution(year, month, day):
    if year < 2016 or year > 2100:
        return "INVALID"

    days_in_month = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        days_in_month[2] = 29

    if month < 1 or month > 12 or day < 1 or day > days_in_month[month]:
        return "INVALID"

    total_days = 0
    for y in range(2016, year):
        total_days += 365 + (1 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 0)

    for m in range(1, month):
        total_days += days_in_month[m]

    total_days += day

    weekday = ["THU", "FRI", "SAT", "SUN", "MON", "TUE", "WED"]
    return weekday[total_days % 7]

