def solution(players, m, k):
    if k >= len(players):
        return 0
    needed_servers = max(0, (players[k] + m - 1) // m)
    additional_servers = max(0, needed_servers - (0 if k == 0 else (players[k-1] + m - 1) // m))
    return additional_servers + solution(players, m, k + 1)

