def solution(cacheSize, cities):
    def access_city(cache, city, time):
        if city.lower() in cache:
            return time + 1, cache  # Hit
        else:
            if len(cache) < cacheSize:
                cache.append(city.lower())
            else:
                cache.pop(0)
                cache.append(city.lower())
            return time + 5, cache  # Miss

    def process_cities(cities, cache, time):
        if not cities:
            return time
        city = cities[0]
        new_time, new_cache = access_city(cache, city, time)
        return process_cities(cities[1:], new_cache, new_time)

    return process_cities(cities, []) if cacheSize > 0 else len(cities) * 5

