def solution(number, limit, power):
    divisors_count = [0] * (number + 1)
    for i in range(1, number + 1):
        for j in range(i, number + 1, i):
            divisors_count[j] += 1
    total_power = 0
    for count in divisors_count[1:]:
        total_power += min(count, limit) if count <= limit else power
    return total_power

