def solution(n, roads, sources, destination):
    import heapq
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)
        graph[v].append(u)

    dist = {i: float('inf') for i in range(1, n + 1)}
    dist[destination] = 0
    pq = [(0, destination)]

    while pq:
        d, node = heapq.heappop(pq)
        if d > dist[node]:
            continue
        for neighbor in graph[node]:
            new_dist = d + 1
            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                heapq.heappush(pq, (new_dist, neighbor))

    return [dist[source] if dist[source] != float('inf') else -1 for source in sources]

def solution(food):
    def backtrack(index, current):
        if index == len(food):
            if sum(current) % 2 == 0:
                results.append(''.join(str(i) * (current[i] // 2) for i in range(len(current))))
            return
        for i in range(0, food[index] + 1):
            current[index] = i
            backtrack(index + 1, current)
            current[index] = 0

    results = []
    backtrack(0, [0] * len(food))
    return results

