def solution(n, build_frame):
    pillars = set()
    beams = set()

    def can_place_pillar(x, y):
        return y == 0 or (x, y - 1) in pillars or (x, y) in beams or (x - 1, y) in beams

    def can_place_beam(x, y):
        return ((x, y - 1) in pillars or (x + 1, y - 1) in pillars) or ((x - 1, y) in beams and (x + 1, y) in beams)

    def can_remove_pillar(x, y):
        if (x, y) not in pillars:
            return False
        pillars.remove((x, y))
        if any(not can_place_pillar(px, py) for px, py in pillars) or any(not can_place_beam(bx, by) for bx, by in beams):
            pillars.add((x, y))
            return False
        pillars.add((x, y))
        return True

    def can_remove_beam(x, y):
        if (x, y) not in beams:
            return False
        beams.remove((x, y))
        if any(not can_place_pillar(px, py) for px, py in pillars) or any(not can_place_beam(bx, by) for bx, by in beams):
            beams.add((x, y))
            return False
        beams.add((x, y))
        return True

    for x, y, a, b in build_frame:
        if b == 1:  # 설치
            if a == 0 and can_place_pillar(x, y):
                pillars.add((x, y))
            elif a == 1 and can_place_beam(x, y):
