def solution(clockHands):
    from collections import deque

    n = len(clockHands)
    m = len(clockHands[0])
    target = 0
    for i in range(n):
        for j in range(m):
            target |= (clockHands[i][j] % 4) << (i * m + j)

    def rotate(state, x, y):
        state ^= (1 << (x * m + y))
        if x > 0: state ^= (1 << ((x - 1) * m + y))
        if x < n - 1: state ^= (1 << ((x + 1) * m + y))
        if y > 0: state ^= (1 << (x * m + (y - 1)))
        if y < m - 1: state ^= (1 << (x * m + (y + 1)))
        return state

    visited = set()
    queue = deque([(0, 0)])
    visited.add(0)
    steps = 0

    while queue:
        for _ in range(len(queue)):
            current = queue.popleft()
            if current == target:
                return steps
            for i in range(n):
                for j in range(m):
                    next_state = rotate(current, i, j)
                    if next_state not in visited:
                        visited.add(next_state)
                        queue.append(next_state)
        steps += 1

    return -1

