    from collections import deque, defaultdict
    import heapq

    def bfs(start):
        q = deque([start])
        distances = {start: 0}
        while q:
            x, y, z = q.popleft()
            for dx, dy, dz in [(0, 0, 1), (0, 0, -1), (0, 1, 0), (0, -1, 0), (1, 0, 0), (-1, 0, 0)]:
                nx, ny, nz = x + dx, y + dy, z + dz
                if 0 <= nx < h and 0 <= ny < len(grid[0]) and 0 <= nz < len(grid[0][0]) and grid[nx][ny][nz] == 0:
                    if (nx, ny, nz) not in distances:
                        distances[(nx, ny, nz)] = distances[(x, y, z)] + 1
                        q.append((nx, ny, nz))
        return distances

    graph = defaultdict(list)
    panel_positions = {i + 1: panels[i] for i in range(len(panels))}
    for a, b in seqs:
        graph[a].append(b)

    distances = {}
    for panel in panel_positions:
        distances[panel] = bfs(panel_positions[panel])

    indegree = {i: 0 for i in range(1, len(panels) + 1)}
    for a in graph:
        for b in graph[a]:
            indegree[b] += 1

    min_heap = []
    for i in range(1, len(panels) + 1):
        if indegree[i] == 0:
            heapq.heappush(min_heap, i)

    result = []
    while min_heap:
        current = heapq.heappop(min_heap)
        result.append(current)
        for neighbor in graph[current]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(min_heap, neighbor)

