def solution(info, edges):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    max_sheep = 0
    visited = set()

    def dfs(node, sheep, wolf, path):
        nonlocal max_sheep
        if wolf >= sheep:
            return
        max_sheep = max(max_sheep, sheep)
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor, sheep + (info[neighbor] == 0), wolf + (info[neighbor] == 1), path + [neighbor])
        visited.remove(node)

    dfs(0, 1, 0, [0])
    return max_sheep

