def solution(n, k, enemy):
    def dfs(rounds, soldiers, shields):
        if rounds == len(enemy):
            return 0
        if soldiers >= enemy[rounds]:
            return 1 + dfs(rounds + 1, soldiers - enemy[rounds], shields)
        if shields > 0:
            return max(dfs(rounds + 1, soldiers, shields - 1), dfs(rounds + 1, soldiers, shields))
        return 0

    return dfs(0, n, k)

