def solution(board, commands):
    N, M = len(board), len(board[0])
    result = []

    for command in commands:
        direction, steps = command
        steps = steps % (N if direction in [0, 1] else M)

        if direction == 0:  # 상하 이동
            for i in range(M):
                board[(i + steps) % N][i] = board[i][i]

        elif direction == 1:  # 하상 이동
            for i in range(M):
                board[(i - steps) % N][i] = board[i][i]

        elif direction == 2:  # 좌우 이동
            for i in range(N):
                board[i][(i + steps) % M] = board[i][i]

        elif direction == 3:  # 우좌 이동
            for i in range(N):
                board[i][(i - steps) % M] = board[i][i]

        result.append(board)

    return result

