def solution(maze):
    rows = len(maze)
    cols = len(maze[0])
    red_pos = blue_pos = None

    for i in range(rows):
        for j in range(cols):
            if maze[i][j] == 'R':
                red_pos = (i, j)
            elif maze[i][j] == 'B':
                blue_pos = (i, j)

    def move(pos, direction):
        x, y = pos
        if direction == 'up':
            x -= 1
        elif direction == 'down':
            x += 1
        elif direction == 'left':
            y -= 1
        elif direction == 'right':
            y += 1
        if 0 <= x < rows and 0 <= y < cols and maze[x][y] != '#':
            return (x, y)
        return pos

    directions = ['up', 'down', 'left', 'right']
    for direction in directions:
        new_red_pos = move(red_pos, direction)
        new_blue_pos = move(blue_pos, direction)

        if new_red_pos == new_blue_pos:
            continue

        if maze[new_red_pos[0]][new_red_pos[1]] == 'G':
            return True
        if maze[new_blue_pos[0]][new_blue_pos[1]] == 'G':
            continue

        red_pos = new_red_pos
        blue_pos = new_blue_pos

        if red_pos == blue_pos:
            continue

    return False

def solution(commands):
    parent = {}
    value = {}

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    def set_value(x, val):
        root = find(x)
        value[root] = val

    for command in commands:
        cmd = command.split()
        if cmd[0] == "UPDATE":
            if len(cmd) == 4:
                r, c, val = int(cmd[1]), int(cmd[2]), cmd[3]
                cell = (r, c)
                if cell not in parent:
                    parent[cell] = cell
                set_value(cell, val)
            else:
                val1, val2 = cmd[1], cmd[2]
                for cell in list(parent.keys()):
                    if value.get(find(cell)) == val1:
                        set_value(cell, val2)
        elif cmd[0] == "MERGE":
            r1, c1, r2, c2 = int(cmd[1]), int(cmd[2]), int(cmd[3]), int(cmd[4])
            cell1 = (r1, c1)
            cell2 = (r2, c2)
            if cell1 not in parent:
                parent[cell1] = cell1
            if cell2 not in parent:
                parent[cell2] = cell2
            union(cell1, cell2)
        elif cmd[0] == "UNMERGE":
            r, c = int(cmd[1]), int(cmd[2])
            cell = (r, c)
            root = find(cell)
            if root in parent:
                for k in list(parent.keys()):
                    if find(k) == root and k != cell:
                        parent[k] = k
                if root in value:
                    set_value(cell, value[root])
        elif cmd[0] == "PRINT":
            r, c = int(cmd[1]), int(cmd[2])
            cell = (r, c)
            root = find(cell)
            print(value.get(root, ""))

def solution(dist_limit, split_limit):
    def count_leaves(depth):
        if depth == 0:
            return 1
        total_leaves = 0
        for i in range(2, 4):
            if depth - 1 >= 0:
                total_leaves += count_leaves(depth - 1) * i
        return total_leaves

    return count_leaves(dist_limit) if split_limit > 0 else 0

