def solution(relation):
    from itertools import combinations

    def is_unique(candidate):
        seen = set()
        for row in relation:
            key = tuple(row[col] for col in candidate)
            if key in seen:
                return False
            seen.add(key)
        return True

    def is_minimal(candidate):
        for i in range(1, len(candidate)):
            for subset in combinations(candidate, i):
                if subset in candidates:
                    return False
        return True

    num_cols = len(relation[0])
    candidates = []

    for r in range(1, num_cols + 1):
        for cols in combinations(range(num_cols), r):
            if is_unique(cols) and is_minimal(cols):
                candidates.append(cols)

    return len(candidates)

