import heapq
from collections import defaultdict

def solution(N, road, K):
    answer = 0
    graph = defaultdict(list)
    dist = {}
    for i in range(1,N+1):
        dist[i]=500000
    dist[1]=0
    q=[(1,0)] #정점, 가중치, 방문

    for u,v,w in road:
        graph[u].append((v,w))
        graph[v].append((u,w))

    while q:
        node, d = heapq.heappop(q)
        if d>dist[node]:continue
        dist[node]=d
        for v,w in graph[node]:
            weight = d+w
            heapq.heappush(q,(v,weight))
    for i in dist:
        if dist[i]<=K:
            answer+=1
    return answer

