def solution(n, infection, edges, k):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for u, v, t in edges:
        graph[u].append((v, t))
        graph[v].append((u, t))

    def bfs(start, pipe_type):
        visited = [False] * (n + 1)
        queue = deque([start])
        visited[start] = True
        infected_count = 0

        while queue:
            node = queue.popleft()
            infected_count += infection[node - 1]
            for neighbor, t in graph[node]:
                if not visited[neighbor] and t == pipe_type:
                    visited[neighbor] = True
                    queue.append(neighbor)

        return infected_count

    max_infection = 0
    for pipe_type in ['A', 'B', 'C']:
        for i in range(1, n + 1):
            max_infection = max(max_infection, bfs(i, pipe_type))

    return min(max_infection, k)

