def solution(expression):
    import re
    from itertools import permutations

    numbers = list(map(int, re.findall(r'\d+', expression)))
    operators = re.findall(r'[\+\-\*]', expression)

    def calculate(a, b, op):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b

    def evaluate(nums, ops, precedence):
        for op in precedence:
            stack_nums = []
            stack_ops = []
            i = 0
            while i < len(nums):
                stack_nums.append(nums[i])
                if i < len(ops) and ops[i] == op:
                    b = stack_nums.pop()
                    a = stack_nums.pop()
                    stack_nums.append(calculate(a, b, op))
                i += 1
                if i < len(ops):
                    stack_ops.append(ops[i])
            nums, ops = stack_nums, stack_ops
        return abs(nums[0])

    max_result = 0
    for precedence in permutations(set(operators)):
        result = evaluate(numbers, operators, precedence)
        max_result = max(max_result, result)

    return max_result

def solution(n, infection, edges, k):
    def dfs(node, visited):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited)

    graph = [[] for _ in range(n)]
    pipe_type = {}
    for u, v, t in edges:
        graph[u - 1].append(v - 1)
        graph[v - 1].append(u - 1)
        pipe_type[(u - 1, v - 1)] = t
        pipe_type[(v - 1, u - 1)] = t

    def open_pipes(pipe_color, current_infection, depth):
        if depth == k:
            return current_infection

        new_infection = current_infection[:]
        visited = [False] * n

        for i in range(n):
            if new_infection[i] and not visited[i]:
                dfs(i, visited)

        max_infection = sum(visited)
        for color in ['A', 'B', 'C']:
            if color in pipe_color:
                for u, v in pipe_color[color]:
                    if not new_infection[u] and not new_infection[v]:
                        new_infection[u] = True
                        new_infection[v] = True
                        max_infection = max(max_infection, open_pipes(pipe_color, new_infection, depth + 1))
                        new_infection[u] = False
                        new_infection[v] = False

        return max_infection

    pipe_color = {'A': [], 'B': [], 'C': []}
    for u, v, t in edges:
        pipe_color[t].append((u - 1, v - 1))

    return open_pipes(pipe_color, infection, 0)

