    def install(start, end, idx):
        if start > end:
            return 0
        if idx >= len(stations):
            return (end - start + 1 + 2 * W) // (2 * W + 1)
        s = stations[idx] - W
        e = stations[idx] + W
        if start > e:
            return install(start, end, idx + 1)
        new_start = max(start, e + 1)
        return install(new_start, end, idx + 1)

    return install(1, N, 0) if cover(1, N, 0) else -1

