def solution(board, r, c):
    from collections import defaultdict, deque

    def find_card_positions():
        positions = defaultdict(list)
        for i in range(10):
            for j in range(10):
                if board[i][j] != 0:
                    positions[board[i][j]].append((i, j))
        return positions

    def bfs(start, target):
        queue = deque([start])
        visited = set([start])
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        distance = 0

        while queue:
            for _ in range(len(queue)):
                x, y = queue.popleft()
                if board[x][y] == target:
                    return distance
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < 10 and 0 <= ny < 10 and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        queue.append((nx, ny))
                for i in range(10):
                    if board[x][i] != 0 and (x, i) not in visited:
                        visited.add((x, i))
                        queue.append((x, i))
                    if board[i][y] != 0 and (i, y) not in visited:
                        visited.add((i, y))
                        queue.append((i, y))
        return float('inf')

    positions = find_card_positions()
    pairs = list(positions.keys())
    total_moves = 0

    for i in range(0, len(pairs), 2):
        first_card = pairs[i]
        second_card = pairs[i + 1]
        first_pos = positions[first_card][0]
        second_pos = positions[second_card][0]

        total_moves += bfs((r, c), first_pos) + bfs(first_pos, second_pos)
        r, c = second_pos

    return total_moves

def solution(cacheSize, cities):
    answer = 5    #처음엔 데이터가 캐시에 존재하지 않으므로 5부터 시작한다.

    #(예외처리) cache의 크기가 0인 경우, 모두 cache miss로 처리한다.(ex 입출력 예제 6번)
    if(cacheSize==0):
        return len(cities)*5

    cache=[cities.pop().lower()]
    #도시이름 배열의 길이만큼 반복
    for x in range(len(cities)+1):
        if not cities:
            return answer
        # cache hit
