        if i in cache:
            answer+=1
            cache.remove(i)
            cache.append(cities.pop().lower())
        #cache miss
        else:
            if(len(cache)==cacheSize):
                cache.pop(0)    # (=) del cache[0]
            cache.append(cities.pop().lower())
            answer+=5

    return answer

