    answer = [n-i-1 for i in range(n)]
    check = [True if 1 < i else False for i in prices]

    for i, v in enumerate(prices):
        for j in range(i):
            if v < prices[j] and check[j]:
                check[j] = False
                answer[j] = i-j

    return answer


