def solution(number, limit, power):
    def count_divisors(n, i=1, count=0):
        if i > n:
            return count
        if n % i == 0:
            count += 1
        return count_divisors(n, i + 1, count)

    def calculate_power(n):
        divisors = count_divisors(n)
        if divisors > limit:
            return power
        return divisors

    if number < 1:
        return 0
    return sum(calculate_power(i) for i in range(1, number + 1))

def solution(N):
