def solution(land):
    def dfs(x, y):
        if x < 0 or x >= len(land) or y < 0 or y >= len(land[0]) or land[x][y] == 0:
            return 0
        land[x][y] = 0
        size = 1
        size += dfs(x + 1, y)
        size += dfs(x - 1, y)
        size += dfs(x, y + 1)
        size += dfs(x, y - 1)
        return size

    max_size = 0
    for i in range(len(land)):
        for j in range(len(land[0])):
            if land[i][j] == 1:
                max_size = max(max_size, dfs(i, j))
    return max_size

