def solution(n):
    MOD = 1000000007
    if n == 1:
        return 1
    elif n == 2:
        return 2
    elif n == 3:
        return 4
    elif n == 4:
        return 8

    dp = [0] * (n + 1)
    dp[1], dp[2], dp[3], dp[4] = 1, 2, 4, 8

    for i in range(5, n + 1):
        dp[i] = (dp[i - 1] + dp[i - 2] + dp[i - 3] + dp[i - 4]) % MOD

    return dp[n]

