def solution(n, computers):
    def find(x):
        if parent[x] < 0:
            return x
        parent[x] = find(parent[x])
        return parent[x]

    def merge(a, b):
        a = find(a)
        b = find(b)
        if a != b:
            parent[a] += parent[b]
            parent[b] = a

    parent = [-1 for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if computers[i][j]:
                merge(i, j)   
    return len([p for p in parent if p < 0])

