    all = w * h
    x, y = w, h # x는 최대 공약수
    while y:
        x, y = y, x % y
    # 수학을 이용한 간편한 풀이
    # answer = (w//x - 1) + (h//x - 1) + 1
    # return all - answer * x
    if w == h:
        return all - w
    elif h > w:
        for i in range(w // x):
            answer += math.ceil(h*(i+1)/w) - int(h * i / w)
    else:
        for i in range(h // x):
            answer += math.ceil(w*(i + 1)/h) - int(w * i / h)

    return all - answer * x

def solution(dartResult):
    idx = 0
    area = {'S': 1, 'D': 2, 'T': 3}
    temp_score = [0] * 4
    for i in range(1, 4):
        if dartResult[idx + 1] in [str(n) for n in range(10)]:
            temp_score[i] = int(dartResult[idx] + dartResult[idx + 1]) ** area[dartResult[idx + 2]]
            idx += 1
        else:
            temp_score[i] = int(dartResult[idx]) ** area[dartResult[idx + 1]]
        if i != 3:
            if dartResult[idx + 2] in ['*', '#']:
                if dartResult[idx + 2] == '*':
                    temp_score[i - 1] = temp_score[i - 1] * 2
                    temp_score[i] = temp_score[i] * 2
                else:
                    temp_score[i] = temp_score[i] * (-1)
                idx += 3
            else:
                idx += 2
        else:
            if idx + 2 != len(dartResult):
                if dartResult[idx + 2] in ['*', '#']:
                    if dartResult[idx + 2] == '*':
                        temp_score[i - 1] = temp_score[i - 1] * 2
                        temp_score[i] = temp_score[i] * 2
                    else:
                        temp_score[i] = temp_score[i] * (-1)
    return sum(temp_score)

