def solution(n):
    if n < 2:
        return 0
    size = (n // 2) + 1
    is_prime = bytearray(size)
    is_prime[0] = 1
    for i in range(3, int(n**0.5) + 1, 2):
        if is_prime[i // 2] == 0:
            for j in range(i * i, n + 1, i * 2):
                is_prime[j // 2] = 1
    count = 1 if n >= 2 else 0
    count += size - sum(is_prime)
    return count

def solution(n, weak, dist):
    weak = weak + [w + n for w in weak]
    m = len(weak)

    def dfs(start, count, friends):
        if count == len(dist):
            return float('inf')
        if start >= m // 2:
            return 0
        min_friends = float('inf')
        for i in range(start, m):
            if weak[i] - weak[start] <= dist[count]:
                min_friends = min(min_friends, dfs(i + 1, count + 1, friends))
        return min_friends + 1

    return dfs(0, 0, dist) if weak else 0

def solution(expression):
    answer = []
    calc_lst = [['+', '-', '*'], ['+', '*', '-'], ['*', '+', '-'], ['*', '-', '+'], ['-', '*', '+'], ['-', '+', '*']]
    for a, b, c in calc_lst:
        tmp_lst = []
        for e in expression.split(a):
            tmp = [f'({i})' for i in e.split(b)]
            tmp_lst.append(f'({b.join(tmp)})')
        answer.append(abs(eval(a.join(tmp_lst))))

    return max(answer)

