def solution(maze):
    def move(red, blue, turns):
        if red == target_red and blue == target_blue:
            return turns
        if turns >= max_turns:
            return float('inf')

        min_turns = float('inf')
        for dr, dc in directions:
            new_red, red_out = slide(red, dr, dc)
            new_blue, blue_out = slide(blue, dr, dc)
            if new_blue == target_blue:
                continue
            if new_red == new_blue:
                if red_out:
                    new_red = red
                else:
                    new_blue = blue
            if new_red != red or new_blue != blue:
                min_turns = min(min_turns, move(new_red, new_blue, turns + 1))

        return min_turns

    def slide(pos, dr, dc):
        r, c = pos
        while 0 <= r + dr < n and 0 <= c + dc < m and maze[r + dr][c + dc] != '#':
            r += dr
            c += dc
            if (r, c) == target_red or (r, c) == target_blue:
                break
        return (r, c), (r + dr < 0 or r + dr >= n or c + dc < 0 or c + dc >= m)

    n, m = len(maze), len(maze[0])
    target_red = (0, 0)
    target_blue = (n - 1, m - 1)
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    max_turns = 10
    red_start = (0, 1)
    blue_start = (1, 0)

    return move(red_start, blue_start, 0) if maze[red_start[0]][red_start[1]] != '#' and maze[blue_start[0]][blue_start[1]] != '#' else -1

