def solution(n, infection, edges, k):
    def dfs(current_infection, actions_left):
        if actions_left == 0:
            return current_infection.count(1)

        max_infected = current_infection.count(1)
        for i in range(n):
            if current_infection[i] == 0:
                current_infection[i] = 1
                for neighbor in graph[i]:
                    if current_infection[neighbor] == 0:
                        current_infection[neighbor] = 1
                max_infected = max(max_infected, dfs(current_infection, actions_left - 1))
                current_infection[i] = 0
                for neighbor in graph[i]:
                    if current_infection[neighbor] == 1:
                        current_infection[neighbor] = 0
        return max_infected

    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    return dfs(infection[:], k)

