    max_dungeons = 0
    for order in permutations(dungeons):
        current_fatigue = k
        count = 0
        for min_fatigue, consume_fatigue in order:
            if current_fatigue >= min_fatigue:
                current_fatigue -= consume_fatigue
                count += 1
            else:
