def solution(triangle):
    l = len(triangle)
    for i in range(1, l):
        ll = len(triangle[i])
        for j in range(ll):
            if j == 0:
                triangle[i][j] += triangle[i-1][j]
            elif j == ll-1:
                triangle[i][j] += triangle[i-1][j-1]
            else:
                triangle[i][j] += max(triangle[i-1][j-1], triangle[i-1][j])
    return max(triangle[-1])

