def solution(n, k):
    def factorial(x):
        if x == 0 or x == 1:
            return 1
        return x * factorial(x - 1)

    def get_permutation(sequence, k):
        if len(sequence) == 0:
            return []
        n = len(sequence)
        fact = factorial(n - 1)
        index = (k - 1) // fact
        return [sequence[index]] + get_permutation(sequence[:index] + sequence[index + 1:], k - index * fact)

    sequence = list(range(1, n + 1))
    return get_permutation(sequence, k)

