        x1, y1, x2, y2 = query
        x1 -= 1
        y1 -= 1
        x2 -= 1
        y2 -= 1

        border = []
        for j in range(y1, y2 + 1):
            border.append(matrix[x1][j])
        for i in range(x1 + 1, x2 + 1):
            border.append(matrix[i][y2])
        for j in range(y2 - 1, y1 - 1, -1):
