            idx += 1
        for i in range(x2 - 1, x1, -1):
            matrix[i][y1] = sorted_border[idx]
            idx += 1

        return sorted_border[-1]

    matrix = [[j + i * columns + 1 for j in range(columns)] for i in range(rows)]
