def solution(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    cycle_lengths = []

    def dfs(r, c, path):
        if visited[r][c]:
            if (r, c) in path:
                cycle_start = path.index((r, c))
                cycle_length = len(path) - cycle_start
                cycle_lengths.append(cycle_length)
            return

        visited[r][c] = True
        path.append((r, c))

        if grid[r][c] == 'L':
            next_r, next_c = r, (c - 1) % cols
        elif grid[r][c] == 'R':
            next_r, next_c = r, (c + 1) % cols
        else:  # 'S'
            next_r, next_c = (r + 1) % rows, c

        dfs(next_r, next_c, path)
        path.pop()

    for i in range(rows):
        for j in range(cols):
            if not visited[i][j]:
                dfs(i, j, [])

    return cycle_lengths

