    def jaccard_similarity(set1, set2):
        intersection = len(set1.intersection(set2))
        union = len(set1.union(set2))
        return intersection / union if union != 0 else 0

    def group_titles(titles, index=0, groups=None):
        if groups is None:
            groups = []
        if index >= len(titles):
            return groups

        current_title = titles[index]
        current_set = set(current_title)
        found_group = False

        for group in groups:
            if jaccard_similarity(current_set, set(group[0])) >= 0.5:
                group.append(current_title)
                found_group = True
                break

        if not found_group:
            groups.append([current_title])

        return group_titles(titles, index + 1, groups)

