def solution(queue1, queue2):
    total_sum = sum(queue1) + sum(queue2)
    if total_sum % 2 != 0:
        return -1
    target = total_sum // 2
    q1, q2 = sum(queue1), sum(queue2)
    p1, p2 = 0, 0
    len1, len2 = len(queue1), len(queue2)

    while p1 < len1 + len2:
        if q1 == target:
            return p1
        if q1 < target:
            if p2 < len2:
                q1 += queue2[p2]
                p2 += 1
            else:
                break
        else:
            if p1 < len1:
                q1 -= queue1[p1]
                p1 += 1
            else:
                break
    return -1

