    def bfs(start, target):
        queue = deque([start])
        visited = set()
        visited.add(start)
        time = 0

        while queue:
            for _ in range(len(queue)):
                x, y = queue.popleft()
                if (x, y) == target:
                    return time
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < len(maps) and 0 <= ny < len(maps[0]) and (nx, ny) not in visited and maps[nx][ny] != 'X':
                        visited.add((nx, ny))
                        queue.append((nx, ny))
            time += 1
        return float('inf')

    start = end = lever = None
    for i in range(len(maps)):
        for j in range(len(maps[0])):
            if maps[i][j] == 'S':
                start = (i, j)
            elif maps[i][j] == 'L':
                lever = (i, j)
            elif maps[i][j] == 'E':
                end = (i, j)

    to_lever = bfs(start, lever)
    to_exit = bfs(lever, end)

    return to_lever + to_exit if to_lever != float('inf') and to_exit != float('inf') else -1

