import heapq

def solution(N, road, K):
    q = []
    INF = int(1e9)
    graph = [[] for _ in range(N + 1)]
    for a, b, c in road:
        graph[a].append((b, c))
        graph[b].append((a, c))

    dist = [INF] * (N + 1)
    dist[1] = 0
    heapq.heappush(q, (0, 1))
    while q:
        cur_time, cur_idx = heapq.heappop(q)
        if dist[cur_idx] < cur_time:
            continue
        for next_idx, cost in graph[cur_idx]:
            if cur_time + cost < dist[next_idx]:
                dist[next_idx] = cur_time + cost
                heapq.heappush(q, (dist[next_idx], next_idx))       

    return bisect_right(sorted(dist[1:]), K)

def solution(dirs):
    def move(x, y, direction, visited):
        if direction == 'U':
            new_x, new_y = x, y + 1
        elif direction == 'D':
            new_x, new_y = x, y - 1
        elif direction == 'R':
            new_x, new_y = x + 1, y
        elif direction == 'L':
            new_x, new_y = x - 1, y
        else:
            return 0

        if not (-5 <= new_x <= 5 and -5 <= new_y <= 5):
            return 0

        path = (x, y, new_x, new_y)
        reverse_path = (new_x, new_y, x, y)

        if path not in visited and reverse_path not in visited:
            visited.add(path)
            return 1 + move(new_x, new_y, direction, visited)

        return move(new_x, new_y, direction, visited)

    visited = set()
    length = 0
    for direction in dirs:
        length += move(0, 0, direction, visited)
    return length

