def solution(n, s, a, b, fares):
    from collections import defaultdict
    import heapq

    graph = defaultdict(list)
    for u, v, w in fares:
        graph[u].append((v, w))
        graph[v].append((u, w))

    def dijkstra(start):
        distances = {i: float('inf') for i in range(1, n + 1)}
        distances[start] = 0
        pq = [(0, start)]
        while pq:
            current_distance, current_node = heapq.heappop(pq)
            if current_distance > distances[current_node]:
                continue
            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(pq, (distance, neighbor))
        return distances

    def find_min_fare(current, a, b, total_fare):
        if current == a and current == b:
            return total_fare
        min_fare = float('inf')
        for neighbor, fare in graph[current]:
            new_fare = total_fare + fare
            if neighbor == a:
                min_fare = min(min_fare, find_min_fare(neighbor, a, b, new_fare))
            elif neighbor == b:
                min_fare = min(min_fare, find_min_fare(neighbor, a, b, new_fare))
            else:
                min_fare = min(min_fare, find_min_fare(neighbor, a, b, new_fare))
        return min_fare

    min_total_fare = float('inf')
    distances_from_start = dijkstra(s)
    for i in range(1, n + 1):
        if distances_from_start[i] < float('inf'):
            fare_to_i = distances_from_start[i]
            fare_to_a = dijkstra(i)[a]
            fare_to_b = dijkstra(i)[b]
            total_fare = fare_to_i + fare_to_a + fare_to_b
            min_total_fare = min(min_total_fare, total_fare)

    return min_total_fare

