    for i in range(len(line)):
        for j in range(i + 1, len(line)):
            A1, B1, C1 = line[i]
            A2, B2, C2 = line[j]
            det = A1 * B2 - A2 * B1
            if det != 0:
                x = (B1 * C2 - B2 * C1) / det
                y = (A2 * C1 - A1 * C2) / det
                if x.is_integer() and y.is_integer():
                    points.add((int(x), int(y)))
    if not points:
        return []
    min_x = min(p[0] for p in points)
