    min_y = min(p[1] for p in points)
    max_y = max(p[1] for p in points)
    grid = [['.'] * (max_x - min_x + 1) for _ in range(max_y - min_y + 1)]
    for x, y in points:
        grid[max_y - y][x - min_x] = '*'
    return [''.join(row) for row in grid]

