    import math

    def get_position(num):
        return (num // 10, num % 10)

    def dijkstra(start_left, start_right, target):
        queue = [(0, start_left, start_right)]
        distances = {(start_left, start_right): 0}
        while queue:
            current_distance, left, right = heappop(queue)
            if current_distance > distances.get((left, right), math.inf):
                continue
            for num in range(100):
                if num == left or num == right:
                    continue
                new_distance = current_distance + abs(get_position(num)[0] - get_position(left)[0]) + abs(get_position(num)[1] - get_position(left)[1])
                if new_distance < distances.get((num, right), math.inf):
                    distances[(num, right)] = new_distance
                    heappush(queue, (new_distance, num, right))
                new_distance = current_distance + abs(get_position(num)[0] - get_position(right)[0]) + abs(get_position(num)[1] - get_position(right)[1])
                if new_distance < distances.get((left, num), math.inf):
                    distances[(left, num)] = new_distance
                    heappush(queue, (new_distance, left, num))
        return distances

    left_start, right_start = 44, 66
    distances = dijkstra(left_start, right_start, numbers)
    total_time = 0
    for num in numbers:
        total_time += distances.get((left_start, right_start), math.inf)
        if left_start != num and right_start != num:
