def solution(jobs):
    answer, now, start = 0, 0, -1
    work = []
    jobs = list(sorted(jobs, key= lambda k : k[0]))
    jobs = deque(jobs)
    total_cnt = len(jobs)
    while jobs or work:
        while jobs and start < jobs[0][0] <= now:
            w_time, w_access = jobs.popleft()
