        for idx2, com in enumerate(computer):
            if idx1 == idx2:
                continue
            if com == 1:
                graph[idx1].append(idx2)

    keyValue= list(graph.keys())

    while len(keyValue)>0:
        start = keyValue.pop()
        if start not in visited:
            visited.add(start)
            cango = []
            cango.extend(graph[start])
            del graph[start]
            while cango:
                node= cango.pop()
                if node not in visited:
                    visited.add(node)
                    cango.extend(graph[node])
            cnt+=1

    return cnt

