        if index == len(s):
            return 0
        current_value = int(s[index]) if s[index].isdigit() else 0
        return current_value + recursive_convert(s, index + 1) if s[index] != '-' else -current_value + recursive_convert(s, index + 1)

    sign = 1 if s[0] != '-' else -1
    return sign * recursive_convert(s[1:], 0) if len(s) > 1 else sign * int(s[0])

