def solution(play_time, adv_time, logs):
    def bubble_sort(arr):
        n = len(arr)
        for i in range(n):
            for j in range(0, n-i-1):
                if arr[j] > arr[j+1]:
                    arr[j], arr[j+1] = arr[j+1], arr[j]

    time_slots = [0] * (int(play_time) + 1)

    for log in logs:
        start, end = map(int, log.split('-'))
        time_slots[start] += 1
        time_slots[end] -= 1

    for i in range(1, len(time_slots)):
        time_slots[i] += time_slots[i - 1]

    bubble_sort(time_slots)

    max_viewers = 0
    best_start = 0
    current_viewers = sum(time_slots[:int(adv_time)])

    for start in range(1, len(time_slots) - int(adv_time) + 1):
        current_viewers = current_viewers - time_slots[start - 1] + time_slots[start + int(adv_time) - 1]
        if current_viewers > max_viewers:
            max_viewers = current_viewers
            best_start = start

    return str(best_start).zfill(2) + ':' + str(best_start % 60).zfill(2) + ':' + str(best_start // 60).zfill(2)

