def solution(n, paths, gates, summits):
    import heapq
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v, w in paths:
        graph[u].append((v, w))
        graph[v].append((u, w))

    def dijkstra(start):
        intensity = [float('inf')] * (n + 1)
        intensity[start] = 0
        pq = [(0, start)]
        while pq:
            curr_intensity, node = heapq.heappop(pq)
            if curr_intensity > intensity[node]:
                continue
            for neighbor, weight in graph[node]:
                new_intensity = max(curr_intensity, weight)
                if new_intensity < intensity[neighbor]:
                    intensity[neighbor] = new_intensity
                    heapq.heappush(pq, (new_intensity, neighbor))
        return intensity

    min_intensity = float('inf')
    best_summit = None
    for gate in gates:
        intensity_from_gate = dijkstra(gate)
        for summit in summits:
            if intensity_from_gate[summit] < min_intensity:
                min_intensity = intensity_from_gate[summit]
                best_summit = summit
            elif intensity_from_gate[summit] == min_intensity:
                best_summit = min(best_summit, summit)

    return [best_summit, min_intensity]

