def solution(game_board, table):
    def rotate(piece):
        return [list(row) for row in zip(*piece[::-1])]

    def can_place(board, piece, r, c):
        for i in range(len(piece)):
            for j in range(len(piece[0])):
                if piece[i][j] == 1 and (r + i >= len(board) or c + j >= len(board[0]) or board[r + i][c + j] == 1):
                    return False
        return True

    def place(board, piece, r, c):
        for i in range(len(piece)):
            for j in range(len(piece[0])):
                if piece[i][j] == 1:
                    board[r + i][c + j] = 1

    def remove(board, piece, r, c):
        for i in range(len(piece)):
            for j in range(len(piece[0])):
                if piece[i][j] == 1:
                    board[r + i][c + j] = 0

    def backtrack(board, pieces, index):
        if index == len(pieces):
            return True
        piece = pieces[index]
        for _ in range(4):
            for r in range(len(board)):
                for c in range(len(board[0])):
                    if can_place(board, piece, r, c):
                        place(board, piece, r, c)
                        if backtrack(board, pieces, index + 1):
                            return True
                        remove(board, piece, r, c)
            piece = rotate(piece)
        return False

    empty_spaces = []
    for i in range(len(game_board)):
        for j in range(len(game_board[0])):
            if game_board[i][j] == 0:
                if not empty_spaces or (empty_spaces[-1] != (i, j)):
                    empty_spaces.append((i, j))

    pieces = []
    for i in range(len(table)):
        for j in range(len(table[0])):
            if table[i][j] == 1:
                piece = []
                while i < len(table) and table[i][j] == 1:
                    row = []
                    while j < len(table[0]) and table[i][j] == 1:
                        row.append(1)
                        j += 1
                    piece.append(row)
                    i += 1
                pieces.append(piece)
                for x in range(len(piece)):
                    for y in range(len(piece[0])):
                        table[i - len(piece) + x][j - len(piece[0]) + y] = 0

    return 1 if backtrack(game_board, pieces, 0) else 0

