def solution(n, l, r):
    if n == 0:
        return 0
    length = 5 ** n
    mid_start = (length - 5) // 2
    mid_end = mid_start + 5

    if r < 0 or l >= length:
        return 0
    if l <= mid_start < r:
        return solution(n - 1, l, r) + solution(n - 1, mid_start + 1, mid_end - 1)
    elif r < mid_start:
        return solution(n - 1, l, r)
    elif l >= mid_end:
        return solution(n - 1, l - mid_end, r - mid_end)
    else:
        return solution(n - 1, l, mid_start) + solution(n - 1, mid_end, r) + 5

