    m = len(land[0])
    visited = [[False] * m for _ in range(n)]

    def dfs(x, y):
        stack = [(x, y)]
        size = 0
        while stack:
            cx, cy = stack.pop()
            if visited[cx][cy]:
                continue
            visited[cx][cy] = True
            size += land[cx][cy]
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and land[nx][ny] > 0:
                    stack.append((nx, ny))
        return size

    oil_sizes = []
    for i in range(n):
        for j in range(m):
            if land[i][j] > 0 and not visited[i][j]:
                oil_sizes.append(dfs(i, j))

    max_oil = [0] * m
    for j in range(m):
        for i in range(n):
            if land[i][j] > 0:
                max_oil[j] += land[i][j]

    return max(max_oil) + (max(oil_sizes) if oil_sizes else 0)

