                new_flips = [row[:] for row in flips]
                flip(i, j)
                new_flips_tuple = tuple(map(tuple, new_flips))
                if new_flips_tuple not in visited:
                    visited.add(new_flips_tuple)
                    queue.append((new_flips, steps + 1))
                flips = new_flips

    return -1

