def solution(operations):
    import heapq
    min_heap = []
    max_heap = []
    entry_finder = {}
    REMOVED = '<removed>'
    counter = 0

    def add_task(task):
        nonlocal counter
        entry_finder[task] = counter
        heapq.heappush(min_heap, (counter, task))
        heapq.heappush(max_heap, (-counter, task))
        counter += 1

    def remove_task(task):
        entry_finder.pop(task)

    def pop_min():
        while min_heap:
            count, task = heapq.heappop(min_heap)
            if task is not REMOVED:
                remove_task(task)
                return task
        return None

    def pop_max():
        while max_heap:
            count, task = heapq.heappop(max_heap)
            if task is not REMOVED:
                remove_task(task)
                return task
        return None

    for operation in operations:
        op, value = operation.split()
        if op == "I":
            add_task(int(value))
        elif op == "D":
            if value == "1":
                pop_max()
            elif value == "-1":
                pop_min()

    min_value = pop_min()
    max_value = pop_max()

    if min_value is None and max_value is None:
        return [0, 0]
    return [max_value, min_value]

