def solution(clockHands):
    def rotate(index):
        clockHands[index] = (clockHands[index] + 3) % 12
        if index > 0:
            clockHands[index - 1] = (clockHands[index - 1] + 3) % 12
        if index < len(clockHands) - 1:
            clockHands[index + 1] = (clockHands[index + 1] + 3) % 12

    def all_twelve():
        return all(hand == 0 for hand in clockHands)

    def dfs(index):
        if index == len(clockHands):
            return all_twelve()
        original_state = clockHands[:]
        if dfs(index + 1):
            return True
        rotate(index)
        if dfs(index + 1):
            return True
        clockHands[:] = original_state
        return False

    return dfs(0)

