def solution(begin, target, words):
    if target not in words:
        return 0

    from collections import deque

    def is_one_letter_diff(word1, word2):
        return sum(c1 != c2 for c1, c2 in zip(word1, word2)) == 1

    graph = {word: [] for word in words}
    for i in range(len(words)):
        for j in range(i + 1, len(words)):
            if is_one_letter_diff(words[i], words[j]):
                graph[words[i]].append(words[j])
                graph[words[j]].append(words[i])

    queue = deque([(begin, 0)])
    visited = {begin}

    while queue:
        current_word, steps = queue.popleft()
        if current_word == target:
            return steps + 1

        for neighbor in graph.get(current_word, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, steps + 1))

    return 0

