    for t, r1, c1, r2, c2, d in skill:
        # 공격이면, 내구도 감소
        if t == 1:
            d *= -1
        # 해당하는 좌표를 탐색하며, 공격 or 회복
        for x in range(r1, r2+1):
            for y in range(c1, c2+1):
